    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 84-year-old man with a long history of poorly controlled hypertension and type 2 diabetes presents with a gradual decline in processing speed, executive function, and gait over the past 3 years. The patient has become increasingly apathetic and emotionally labile. There is no clear stepwise pattern. Examination shows a small-stepped and unsteady gait, pseudobulbar affect, and frontal release signs. Brain MRI reveals **extensive confluent periventricular and deep white matter hyperintensities** with relative preservation of cortical gray matter. Which of the following is the most likely diagnosis?', '["Subcortical ischemic vascular dementia (Binswanger''''s disease) \u2014 caused by chronic small vessel disease leading to diffuse white matter injury, executive dysfunction, gait disturbance, and emotional lability", "Alzheimer''''s disease \u2014 characterized by progressive cortical atrophy with prominent hippocampal involvement and early memory loss", "Normal Pressure Hydrocephalus \u2014 defined by enlarged ventricles compressing periventricular white matter with the triad of gait apraxia, dementia, and urinary incontinence", "Frontotemporal dementia \u2014 characterized by frontal and anterior temporal lobe atrophy with prominent behavioral changes and personality deterioration", "Multiple sclerosis \u2014 characterized by periventricular demyelinating plaques with relapsing-remitting neurological deficits in young adults"]'::jsonb, 0, '**Subcortical ischemic vascular dementia (Binswanger''''s disease)** is a subtype of vascular dementia caused by **chronic small vessel disease** (lipohyalinosis, arteriosclerosis) leading to **diffuse white matter injury** (leukoaraiosis). Key features include: (1) **Gradual rather than stepwise decline** (unlike multi-infarct dementia); (2) Prominent **executive dysfunction** (planning, organizing, multitasking) with relatively preserved episodic memory early on; (3) **Gait disturbance** (shuffling, wide-based, or apraxic gait); (4) **Psychomotor slowing**; (5) **Pseudobulbar affect** (involuntary laughing or crying); (6) **Urinary urgency/incontinence**. MRI shows extensive **confluent periventricular and deep white matter hyperintensities** on FLAIR/T2-weighted sequences. The primary risk factor is **chronic hypertension**. Management focuses on aggressive BP control and vascular risk factor modification. (Ref: Hazzard''''s Ch. 72; Current D&T Geriatrics)'),
    (v_topic_id, 'A 83-year-old woman with a long history of poorly controlled hypertension and type 2 diabetes presents with a gradual decline in processing speed, executive function, and gait over the past 2 years. The patient has become increasingly apathetic and emotionally labile. There is no clear stepwise pattern. Examination shows a shuffling, wide-based gait, pseudobulbar affect, and frontal release signs. Brain MRI reveals **extensive confluent periventricular and deep white matter hyperintensities** with relative preservation of cortical gray matter. Which of the following is the most likely diagnosis?', '["Frontotemporal dementia \u2014 characterized by frontal and anterior temporal lobe atrophy with prominent behavioral changes and personality deterioration", "Subcortical ischemic vascular dementia (Binswanger''''s disease) \u2014 caused by chronic small vessel disease leading to diffuse white matter injury, executive dysfunction, gait disturbance, and emotional lability", "Alzheimer''''s disease \u2014 characterized by progressive cortical atrophy with prominent hippocampal involvement and early memory loss", "Multiple sclerosis \u2014 characterized by periventricular demyelinating plaques with relapsing-remitting neurological deficits in young adults", "Normal Pressure Hydrocephalus \u2014 defined by enlarged ventricles compressing periventricular white matter with the triad of gait apraxia, dementia, and urinary incontinence"]'::jsonb, 1, '**Subcortical ischemic vascular dementia (Binswanger''''s disease)** is a subtype of vascular dementia caused by **chronic small vessel disease** (lipohyalinosis, arteriosclerosis) leading to **diffuse white matter injury** (leukoaraiosis). Key features include: (1) **Gradual rather than stepwise decline** (unlike multi-infarct dementia); (2) Prominent **executive dysfunction** (planning, organizing, multitasking) with relatively preserved episodic memory early on; (3) **Gait disturbance** (shuffling, wide-based, or apraxic gait); (4) **Psychomotor slowing**; (5) **Pseudobulbar affect** (involuntary laughing or crying); (6) **Urinary urgency/incontinence**. MRI shows extensive **confluent periventricular and deep white matter hyperintensities** on FLAIR/T2-weighted sequences. The primary risk factor is **chronic hypertension**. Management focuses on aggressive BP control and vascular risk factor modification. (Ref: Hazzard''''s Ch. 72; Current D&T Geriatrics)'),
