-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Cognitive disorders - Alzheimer's, vascular, Lewy body, frontotemporal dementia, MCI - Part 2 (101-200)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-cognitive-disorders' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-cognitive-disorders not found.';
    END IF;

END $$;
COMMIT;
